-- Run after the existing OceanCore quotation/invoice setup. All changes are transactional.
begin;
alter table public.customers add column if not exists trn text;
alter table public.invoices alter column quotation_id drop not null;
alter table public.invoices
 add column if not exists due_date date,
 add column if not exists paid_amount numeric(12,2) not null default 0,
 add column if not exists document_status text not null default 'Issued',
 add column if not exists customer_snapshot jsonb not null default '{}'::jsonb,
 add column if not exists supplier_snapshot jsonb not null default '{}'::jsonb,
 add column if not exists revision integer not null default 1,
 add column if not exists client_token uuid;
update public.invoices set paid_amount=grand_total where payment_status='Paid' and paid_amount=0;
create unique index if not exists oc_invoice_client_token_idx on public.invoices(client_token);
alter table public.invoice_items alter column product_id drop not null;
alter table public.invoice_items add column if not exists unit text not null default 'PCS',add column if not exists position integer not null default 0;
alter table public.invoice_items alter column quantity type numeric(14,3) using quantity::numeric,
 alter column unit_price type numeric(14,2) using unit_price::numeric;
create table if not exists public.billing_settings(id boolean primary key default true check(id),profile jsonb not null default '{}'::jsonb);
insert into public.billing_settings(id,profile) values(true,jsonb_build_object(
 'name','OceanCore Marine Spare Parts','address','Sharjah Industrial Area 2, DUBAI, UNITED ARAB EMIRATES',
 'phone','+971564502513','email','marineoceancore@gmail.com','website','https://oceancoremarine.github.io/',
 'trn','','vat_rate',5,'bank','','account_name','','account_number','','iban','','swift',''
)) on conflict(id) do nothing;
create sequence if not exists public.oc_delivery_number_seq;
create table if not exists public.delivery_notes(
 id bigint generated by default as identity primary key,
 delivery_number text not null unique,
 invoice_id bigint references public.invoices(id) on delete restrict,
 customer_id bigint not null references public.customers(id) on delete restrict,
 delivery_date date not null default current_date,
 status text not null default 'Draft' check(status in ('Draft','Dispatched','Delivered','Cancelled')),
 delivery_address text,customer_trn text,contact text,remarks text,received_by text,delivered_by text,
 customer_snapshot jsonb not null default '{}'::jsonb,supplier_snapshot jsonb not null default '{}'::jsonb,
 revision integer not null default 1,client_token uuid unique,
 created_at timestamptz not null default now(),created_by uuid references auth.users(id)
);
create table if not exists public.delivery_note_items(
 id bigint generated by default as identity primary key,
 delivery_note_id bigint not null references public.delivery_notes(id) on delete cascade,
 invoice_item_id bigint references public.invoice_items(id) on delete set null,
 product_id bigint references public.products(id) on delete set null,
 product_name text not null,part_number text,brand_name text,
 quantity numeric(14,3) not null check(quantity>0),unit text not null default 'PCS',
 unit_price numeric(14,2) not null default 0 check(unit_price>=0),discount numeric(14,2) not null default 0 check(discount>=0),
 position integer not null default 0
);
create index if not exists oc_delivery_invoice_idx on public.delivery_notes(invoice_id);
create index if not exists oc_delivery_item_invoice_idx on public.delivery_note_items(invoice_item_id);
create table if not exists public.billing_audit(
 id bigint generated by default as identity primary key,document_type text not null,document_id bigint not null,
 action text not null,snapshot jsonb,created_at timestamptz not null default now(),created_by uuid references auth.users(id)
);
-- Administrator-only access, including customer addresses and commercial document history.
do $$ declare t text; begin
 foreach t in array array['invoices','invoice_items','billing_settings','delivery_notes','delivery_note_items','billing_audit'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('drop policy if exists "OceanCore billing admins" on public.%I',t);
  execute format('create policy "OceanCore billing admins" on public.%I for all to authenticated using(exists(select 1 from public.admin_users where user_id=auth.uid())) with check(exists(select 1 from public.admin_users where user_id=auth.uid()))',t);
  execute format('grant select,insert,update,delete on public.%I to authenticated',t);
  execute format('revoke all on public.%I from anon',t);
  execute format('drop policy if exists "OceanCore billing admin restriction" on public.%I',t);
  execute format('create policy "OceanCore billing admin restriction" on public.%I as restrictive for all to authenticated using(exists(select 1 from public.admin_users where user_id=auth.uid())) with check(exists(select 1 from public.admin_users where user_id=auth.uid()))',t);
 end loop;
end $$;
grant usage,select on sequence public.delivery_notes_id_seq,public.delivery_note_items_id_seq,public.billing_audit_id_seq,public.oc_delivery_number_seq to authenticated;
-- Fixed-path helpers. These functions are invoker-rights; the caller must be an admin.
create or replace function public.oc_billing_admin() returns void language plpgsql set search_path='' as $$
begin if not exists(select 1 from public.admin_users where user_id=auth.uid()) then raise exception 'Administrator access required' using errcode='42501';end if;end $$;
create or replace function public.oc_billing_totals(p_items jsonb,p_other numeric,p_vat numeric) returns jsonb language plpgsql set search_path='' as $$
declare r jsonb; q numeric; price numeric; d numeric; gross numeric; sub numeric:=0;disc numeric:=0;base numeric;vat numeric;begin
 perform public.oc_billing_admin();
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 200 then raise exception 'Add 1 to 200 items';end if;
 if p_other<0 or p_other<>round(p_other,2) or p_vat<0 or p_vat>100 or p_vat<>round(p_vat,2) then raise exception 'Invalid other charges or VAT rate';end if;
 for r in select value from jsonb_array_elements(p_items) loop
  if char_length(btrim(coalesce(r->>'product_name',''))) not between 1 and 1000 then raise exception 'Each line needs a description';end if;
  q:=(r->>'quantity')::numeric;price:=(r->>'unit_price')::numeric;d:=coalesce((r->>'discount')::numeric,0);
  if q is null or price is null or q<=0 or q>1000000 or q<>round(q,3) or price<0 or price>9999999999.99 or price<>round(price,2) or d<0 or d<>round(d,2) then raise exception 'Invalid quantity, price or discount';end if;
  gross:=round(q*price,2);if d>gross then raise exception 'Line discount exceeds line amount';end if;sub:=sub+gross;disc:=disc+d;
 end loop;
 base:=sub-disc+p_other;vat:=round(base*p_vat/100,2);
 if sub>9999999999.99 or base+vat>9999999999.99 then raise exception 'Invoice exceeds the supported AED range';end if;
 return jsonb_build_object('subtotal',sub,'discount',disc,'other_charges',p_other,'vat_rate',p_vat,'vat_amount',vat,'grand_total',base+vat);
end $$;
create or replace function public.oc_save_invoice(p_id bigint,p_header jsonb,p_items jsonb,p_token uuid) returns jsonb language plpgsql set search_path='' as $$
declare old public.invoices%rowtype; saved public.invoices%rowtype;c public.customers%rowtype;prof jsonb;tot jsonb;r jsonb;prev public.invoice_items%rowtype;lineid bigint;keepids bigint[]:=array[]::bigint[];pos integer:=0;reserved numeric;paid numeric;grand numeric;v_customer bigint;v_status text;v_number text;begin
 perform public.oc_billing_admin();
 if p_id is null then
  if p_token is null then raise exception 'Create token is required';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_token::text));
  select * into saved from public.invoices where client_token=p_token;if found then return jsonb_build_object('id',saved.id,'number',saved.invoice_number,'revision',saved.revision);end if;
 else
  select * into old from public.invoices where id=p_id for update;if not found then raise exception 'Invoice not found';end if;
  if coalesce((p_header->>'revision')::integer,0)<>old.revision then raise exception 'Invoice changed in another session. Reload before saving.' using errcode='40001';end if;
 end if;
 v_customer:=(p_header->>'customer_id')::bigint;select * into c from public.customers where id=v_customer;if not found then raise exception 'Select an existing customer';end if;
 if p_id is not null and v_customer<>old.customer_id and exists(select 1 from public.delivery_notes where invoice_id=p_id and status<>'Cancelled') then raise exception 'Cannot change the customer while an active delivery note is linked';end if;
 select profile into prof from public.billing_settings where id=true;prof:=coalesce(prof,'{}'::jsonb);
 if char_length(coalesce(prof->>'trn',''))>0 and prof->>'trn' !~ '^[0-9]{15}$' then raise exception 'Supplier TRN must contain 15 digits';end if;
 tot:=public.oc_billing_totals(p_items,coalesce((p_header->>'other_charges')::numeric,0),coalesce((p_header->>'vat_rate')::numeric,5));grand:=(tot->>'grand_total')::numeric;paid:=coalesce((p_header->>'paid_amount')::numeric,0);
 if paid<0 or paid>grand or paid<>round(paid,2) then raise exception 'Paid amount must be between zero and the invoice total';end if;
 v_status:=coalesce(p_header->>'document_status','Draft');if v_status not in ('Draft','Issued','Cancelled') then raise exception 'Invalid invoice status';end if;
 if v_status='Cancelled' and paid>0 then raise exception 'A paid invoice cannot be cancelled without first resolving its payment';end if;
 if v_status='Cancelled' and p_id is not null and exists(select 1 from public.delivery_notes where invoice_id=p_id and status<>'Cancelled') then raise exception 'Cancel linked delivery notes before cancelling the invoice';end if;
 if nullif(p_header->>'due_date','') is not null and (p_header->>'due_date')::date<(p_header->>'invoice_date')::date then raise exception 'Due date cannot be before invoice date';end if;
 if p_id is null then
  v_number:=public.next_invoice_number();
  insert into public.invoices(invoice_number,quotation_id,customer_id,invoice_date,due_date,currency,subtotal,discount,other_charges,vat_rate,vat_amount,grand_total,payment_type,payment_status,paid_amount,delivery_terms,notes,document_status,customer_snapshot,supplier_snapshot,created_by,client_token)
  values(v_number,nullif(p_header->>'quotation_id','')::bigint,v_customer,(p_header->>'invoice_date')::date,nullif(p_header->>'due_date','')::date,'AED',(tot->>'subtotal')::numeric,(tot->>'discount')::numeric,(tot->>'other_charges')::numeric,(tot->>'vat_rate')::numeric,(tot->>'vat_amount')::numeric,grand,coalesce(p_header->>'payment_type','Cash'),case when paid>=grand then 'Paid' else 'Unpaid' end,paid,coalesce(p_header->>'delivery_terms',''),nullif(p_header->>'notes',''),v_status,to_jsonb(c),prof,auth.uid(),p_token) returning * into saved;
 else
  update public.invoices set customer_id=v_customer,invoice_date=(p_header->>'invoice_date')::date,due_date=nullif(p_header->>'due_date','')::date,subtotal=(tot->>'subtotal')::numeric,discount=(tot->>'discount')::numeric,other_charges=(tot->>'other_charges')::numeric,vat_rate=(tot->>'vat_rate')::numeric,vat_amount=(tot->>'vat_amount')::numeric,grand_total=grand,payment_type=coalesce(p_header->>'payment_type','Cash'),payment_status=case when paid>=grand then 'Paid' else 'Unpaid' end,paid_amount=paid,delivery_terms=coalesce(p_header->>'delivery_terms',''),notes=nullif(p_header->>'notes',''),document_status=v_status,customer_snapshot=case when v_customer=old.customer_id and old.customer_snapshot<>'{}'::jsonb then old.customer_snapshot else to_jsonb(c) end,supplier_snapshot=case when old.supplier_snapshot='{}'::jsonb then prof else old.supplier_snapshot end,revision=revision+1 where id=p_id returning * into saved;
 end if;
 for r in select value from jsonb_array_elements(p_items) loop
  pos:=pos+1;lineid:=nullif(r->>'id','')::bigint;
  if lineid is not null then
   select * into prev from public.invoice_items where id=lineid and invoice_id=saved.id for update;if not found then raise exception 'Invoice item does not belong to this invoice';end if;
   if lineid=any(keepids) then raise exception 'Duplicate invoice item identifier';end if;
   select coalesce(sum(di.quantity),0) into reserved from public.delivery_note_items di join public.delivery_notes dn on dn.id=di.delivery_note_id where di.invoice_item_id=lineid and dn.status<>'Cancelled';
   if reserved>0 and ((r->>'quantity')::numeric<reserved or coalesce(nullif(r->>'product_id','')::bigint,0)<>coalesce(prev.product_id,0) or coalesce(r->>'part_number','')<>coalesce(prev.part_number,'') or coalesce(nullif(r->>'unit',''),'PCS')<>prev.unit) then raise exception 'Linked delivery quantities or product references cannot be invalidated';end if;
   update public.invoice_items set product_id=nullif(r->>'product_id','')::bigint,product_name=btrim(r->>'product_name'),part_number=nullif(r->>'part_number',''),brand_name=nullif(r->>'brand_name',''),quantity=(r->>'quantity')::numeric,unit_price=(r->>'unit_price')::numeric,discount=coalesce((r->>'discount')::numeric,0),line_total=round((r->>'quantity')::numeric*(r->>'unit_price')::numeric,2)-coalesce((r->>'discount')::numeric,0),unit=coalesce(nullif(r->>'unit',''),'PCS'),position=pos where id=lineid;
  else
   insert into public.invoice_items(invoice_id,product_id,product_name,part_number,brand_name,quantity,unit_price,discount,line_total,unit,position) values(saved.id,nullif(r->>'product_id','')::bigint,btrim(r->>'product_name'),nullif(r->>'part_number',''),nullif(r->>'brand_name',''),(r->>'quantity')::numeric,(r->>'unit_price')::numeric,coalesce((r->>'discount')::numeric,0),round((r->>'quantity')::numeric*(r->>'unit_price')::numeric,2)-coalesce((r->>'discount')::numeric,0),coalesce(nullif(r->>'unit',''),'PCS'),pos) returning id into lineid;
  end if;keepids:=array_append(keepids,lineid);
 end loop;
 if exists(select 1 from public.invoice_items ii join public.delivery_note_items di on di.invoice_item_id=ii.id join public.delivery_notes dn on dn.id=di.delivery_note_id where ii.invoice_id=saved.id and not(ii.id=any(keepids)) and dn.status<>'Cancelled') then raise exception 'Cannot remove an item referenced by an active delivery note';end if;
 delete from public.invoice_items where invoice_id=saved.id and not(id=any(keepids));
 insert into public.billing_audit(document_type,document_id,action,snapshot,created_by) values('invoice',saved.id,case when p_id is null then 'create' else 'edit' end,jsonb_build_object('before',case when p_id is null then null else to_jsonb(old) end,'after',to_jsonb(saved),'items',p_items),auth.uid());
 return jsonb_build_object('id',saved.id,'number',saved.invoice_number,'revision',saved.revision);
end $$;
create or replace function public.oc_save_delivery(p_id bigint,p_header jsonb,p_items jsonb,p_token uuid) returns jsonb language plpgsql set search_path='' as $$
declare old public.delivery_notes%rowtype;saved public.delivery_notes%rowtype;inv public.invoices%rowtype;c public.customers%rowtype;prof jsonb;r jsonb;ii public.invoice_items%rowtype;ids bigint[]:=array[]::bigint[];pos integer:=0;q numeric;used numeric;v_invoice bigint;v_customer bigint;v_status text;begin
 perform public.oc_billing_admin();
 if p_id is null then
  if p_token is null then raise exception 'Create token is required';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(p_token::text));
  select * into saved from public.delivery_notes where client_token=p_token;if found then return jsonb_build_object('id',saved.id,'number',saved.delivery_number,'revision',saved.revision);end if;
 else
  select * into old from public.delivery_notes where id=p_id for update;if not found then raise exception 'Delivery note not found';end if;
  if coalesce((p_header->>'revision')::integer,0)<>old.revision then raise exception 'Delivery note changed in another session. Reload before saving.' using errcode='40001';end if;
 end if;
 v_invoice:=nullif(p_header->>'invoice_id','')::bigint;
 if p_id is not null and v_invoice is distinct from old.invoice_id then raise exception 'A saved delivery note cannot be relinked to another invoice';end if;
 v_customer:=(p_header->>'customer_id')::bigint;select * into c from public.customers where id=v_customer;if not found then raise exception 'Select an existing customer';end if;
 if v_invoice is not null then
  select * into inv from public.invoices where id=v_invoice for update;if not found or inv.document_status='Cancelled' then raise exception 'Linked invoice is unavailable or cancelled';end if;
  if v_customer<>inv.customer_id then raise exception 'Delivery customer must match invoice customer';end if;
 end if;
 v_status:=coalesce(p_header->>'status','Draft');if v_status not in ('Draft','Dispatched','Delivered','Cancelled') then raise exception 'Invalid delivery status';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 200 then raise exception 'Add 1 to 200 delivery items';end if;
 select profile into prof from public.billing_settings where id=true;
 if p_id is null then
  insert into public.delivery_notes(delivery_number,invoice_id,customer_id,delivery_date,status,delivery_address,customer_trn,contact,remarks,received_by,delivered_by,customer_snapshot,supplier_snapshot,created_by,client_token)
  values('OC-DN-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.oc_delivery_number_seq')::text,6,'0'),v_invoice,v_customer,(p_header->>'delivery_date')::date,v_status,p_header->>'delivery_address',coalesce(nullif(p_header->>'customer_trn',''),c.trn),coalesce(nullif(p_header->>'contact',''),c.phone),p_header->>'remarks',p_header->>'received_by',p_header->>'delivered_by',case when v_invoice is null or inv.customer_snapshot='{}'::jsonb then to_jsonb(c) else inv.customer_snapshot end,case when v_invoice is null or inv.supplier_snapshot='{}'::jsonb then coalesce(prof,'{}'::jsonb) else inv.supplier_snapshot end,auth.uid(),p_token) returning * into saved;
 else
  update public.delivery_notes set customer_id=v_customer,delivery_date=(p_header->>'delivery_date')::date,status=v_status,delivery_address=p_header->>'delivery_address',customer_trn=p_header->>'customer_trn',contact=p_header->>'contact',remarks=p_header->>'remarks',received_by=p_header->>'received_by',delivered_by=p_header->>'delivered_by',customer_snapshot=case when v_customer=old.customer_id and old.customer_snapshot<>'{}'::jsonb then old.customer_snapshot else to_jsonb(c) end,revision=revision+1 where id=p_id returning * into saved;
 end if;
 delete from public.delivery_note_items where delivery_note_id=saved.id;
 for r in select value from jsonb_array_elements(p_items) loop
  pos:=pos+1;perform public.oc_billing_totals(jsonb_build_array(r),0,0);q:=(r->>'quantity')::numeric;
  if q is null or q<=0 or q>1000000 or q<>round(q,3) or char_length(btrim(coalesce(r->>'product_name',''))) not between 1 and 1000 or coalesce((r->>'unit_price')::numeric,0)<0 or coalesce((r->>'discount')::numeric,0)<0 then raise exception 'Invalid delivery item';end if;
  if v_invoice is not null then
   select * into ii from public.invoice_items where id=(r->>'invoice_item_id')::bigint and invoice_id=v_invoice;if not found then raise exception 'Delivery item must reference a line of the linked invoice';end if;
   if ii.id=any(ids) then raise exception 'Duplicate invoice item in delivery note';end if;ids:=array_append(ids,ii.id);
   select coalesce(sum(di.quantity),0) into used from public.delivery_note_items di join public.delivery_notes dn on dn.id=di.delivery_note_id where di.invoice_item_id=ii.id and dn.status<>'Cancelled' and dn.id<>saved.id;
   if v_status<>'Cancelled' and used+q>ii.quantity then raise exception 'Delivery quantity exceeds the remaining invoice quantity for %',ii.product_name;end if;
   if coalesce(nullif(r->>'product_id','')::bigint,0)<>coalesce(ii.product_id,0) or coalesce(r->>'part_number','')<>coalesce(ii.part_number,'') or coalesce(nullif(r->>'unit',''),'PCS')<>ii.unit then raise exception 'Linked delivery item references must match the invoice';end if;
  elsif nullif(r->>'invoice_item_id','') is not null then raise exception 'Direct delivery cannot reference an invoice line';end if;
  insert into public.delivery_note_items(delivery_note_id,invoice_item_id,product_id,product_name,part_number,brand_name,quantity,unit,unit_price,discount,position)
  values(saved.id,case when v_invoice is null then null else ii.id end,nullif(r->>'product_id','')::bigint,btrim(r->>'product_name'),r->>'part_number',r->>'brand_name',q,coalesce(nullif(r->>'unit',''),'PCS'),coalesce((r->>'unit_price')::numeric,0),coalesce((r->>'discount')::numeric,0),pos);
 end loop;
 insert into public.billing_audit(document_type,document_id,action,snapshot,created_by) values('delivery',saved.id,case when p_id is null then 'create' else 'edit' end,jsonb_build_object('before',case when p_id is null then null else to_jsonb(old) end,'after',to_jsonb(saved),'items',p_items),auth.uid());
 return jsonb_build_object('id',saved.id,'number',saved.delivery_number,'revision',saved.revision);
end $$;
create or replace function public.oc_convert_quotation(p_id bigint) returns jsonb language plpgsql set search_path='' as $$
declare q public.quotations%rowtype;existing public.invoices%rowtype;items jsonb;result jsonb;begin
 perform public.oc_billing_admin();select * into q from public.quotations where id=p_id for update;if not found then raise exception 'Quotation not found';end if;
 select * into existing from public.invoices where quotation_id=p_id order by id limit 1;if found then return jsonb_build_object('id',existing.id,'number',existing.invoice_number,'revision',existing.revision,'existing',true);end if;
 select jsonb_agg(jsonb_build_object('product_id',product_id,'product_name',product_name,'part_number',part_number,'brand_name',brand_name,'quantity',quantity,'unit_price',unit_price,'discount',discount,'unit','PCS') order by id) into items from public.quotation_items where quotation_id=p_id;
 result:=public.oc_save_invoice(null,jsonb_build_object('customer_id',q.customer_id,'quotation_id',q.id,'invoice_date',current_date,'other_charges',q.other_charges,'vat_rate',q.vat_rate,'paid_amount',0,'document_status','Draft','payment_type',q.payment_type,'delivery_terms','','notes',q.notes),items,pg_catalog.gen_random_uuid());
 update public.quotations set status='Accepted' where id=p_id;return result;
end $$;
create or replace function public.oc_delivery_to_invoice(p_id bigint) returns jsonb language plpgsql set search_path='' as $$
declare dn public.delivery_notes%rowtype;existing public.invoices%rowtype;items jsonb;result jsonb;r record;lineid bigint;prof jsonb;begin
 perform public.oc_billing_admin();select * into dn from public.delivery_notes where id=p_id for update;if not found or dn.status='Cancelled' then raise exception 'Delivery note unavailable or cancelled';end if;
 if dn.invoice_id is not null then select * into existing from public.invoices where id=dn.invoice_id;return jsonb_build_object('id',existing.id,'number',existing.invoice_number,'revision',existing.revision,'existing',true);end if;
 select profile into prof from public.billing_settings where id=true;
 select jsonb_agg(jsonb_build_object('product_id',product_id,'product_name',product_name,'part_number',part_number,'brand_name',brand_name,'quantity',quantity,'unit_price',unit_price,'discount',discount,'unit',unit) order by position,id) into items from public.delivery_note_items where delivery_note_id=p_id;
 result:=public.oc_save_invoice(null,jsonb_build_object('customer_id',dn.customer_id,'invoice_date',current_date,'other_charges',0,'vat_rate',coalesce((prof->>'vat_rate')::numeric,5),'paid_amount',0,'document_status','Draft','payment_type','Cash','delivery_terms','','notes',dn.remarks),items,pg_catalog.gen_random_uuid());
 update public.invoices set customer_snapshot=dn.customer_snapshot,supplier_snapshot=dn.supplier_snapshot where id=(result->>'id')::bigint;
 update public.delivery_notes set invoice_id=(result->>'id')::bigint,revision=revision+1 where id=p_id;
 for r in select id,position from public.delivery_note_items where delivery_note_id=p_id order by position,id loop
  select id into lineid from public.invoice_items where invoice_id=(result->>'id')::bigint and position=r.position;
  update public.delivery_note_items set invoice_item_id=lineid where id=r.id;
 end loop;
 insert into public.billing_audit(document_type,document_id,action,snapshot,created_by) values('delivery',p_id,'convert_to_invoice',result,auth.uid());return result;
end $$;
create or replace function public.oc_delete_document(p_type text,p_id bigint,p_revision integer) returns void language plpgsql set search_path='' as $$
declare snap jsonb;items jsonb;inv public.invoices%rowtype;dn public.delivery_notes%rowtype;begin
 perform public.oc_billing_admin();
 if p_type='invoice' then
  select * into inv from public.invoices where id=p_id for update;if not found then raise exception 'Invoice not found';end if;
  if inv.revision<>p_revision then raise exception 'Invoice changed. Reload before deleting.' using errcode='40001';end if;
  if inv.paid_amount>0 then raise exception 'An invoice with recorded payments cannot be deleted';end if;
  if exists(select 1 from public.delivery_notes where invoice_id=p_id) then raise exception 'Remove eligible linked delivery notes before deleting the invoice';end if;
  snap:=to_jsonb(inv);select jsonb_agg(to_jsonb(i) order by position,id) into items from public.invoice_items i where invoice_id=p_id;
  delete from public.invoice_items where invoice_id=p_id;delete from public.invoices where id=p_id;
 elsif p_type='delivery' then
  select * into dn from public.delivery_notes where id=p_id for update;if not found then raise exception 'Delivery note not found';end if;
  if dn.revision<>p_revision then raise exception 'Delivery note changed. Reload before deleting.' using errcode='40001';end if;
  if dn.status not in ('Draft','Cancelled') then raise exception 'Cancel the delivery note before deleting a dispatched/delivered document';end if;
  snap:=to_jsonb(dn);select jsonb_agg(to_jsonb(i) order by position,id) into items from public.delivery_note_items i where delivery_note_id=p_id;
  delete from public.delivery_notes where id=p_id;
 else raise exception 'Unknown document type';end if;
 insert into public.billing_audit(document_type,document_id,action,snapshot,created_by) values(p_type,p_id,'delete',jsonb_build_object('document',snap,'items',items),auth.uid());
end $$;
-- Helpers and transactional endpoints are never executable by anonymous callers.
do $$ declare f record;begin
 for f in select p.oid::regprocedure as signature from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('oc_billing_admin','oc_billing_totals','oc_save_invoice','oc_save_delivery','oc_convert_quotation','oc_delivery_to_invoice','oc_delete_document') loop
  execute format('revoke all on function %s from public,anon',f.signature);
  execute format('grant execute on function %s to authenticated',f.signature);
 end loop;
end $$;
revoke update,delete on public.billing_audit from authenticated;
commit;
